namespace ghidra.app.plugin.debug;






using docking;
using docking;
using docking.action;
using docking.action;
using generic.theme;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool;
using resources;

public class DomainEventComponentProvider : ComponentProviderAdapter {
	static int LIMIT = 200;
	private static Icon ICON = new GIcon("icon.plugin.debug.domaineventviewer.provider");

	private JTextArea textArea;
	private JScrollPane scrollPane;
	private DockingAction clearAction;
	private List<string> eventList;

	public DomainEventComponentProvider(PluginTool tool, string owner) : base(tool, "Domain Events", owner)
    {
		eventList = new();

		textArea = new JTextArea(10, 80);
		textArea.setEditable(false);
		scrollPane = new JScrollPane(textArea);

		createAction();
		setIcon(ICON);
		setDefaultWindowPosition(WindowPosition.BOTTOM);
		setTitle("Domain Object Event Display");
		setVisible(true);
	}

	/* @Override */
	public JComponent getComponent() {
		return scrollPane;
	}

	/* @Override */
	public void componentHidden() {
		clear();
	}

	private void createAction() {
		clearAction = new DockingAction("Clear Display", getOwner()) {
			/* @Override */
			public void actionPerformed(ActionContext context) {
				clear();
			}
		};

		clearAction.markHelpUnnecessary();
		clearAction.setEnabled(true);
		Icon icon = Icons.CLEAR_ICON;
		clearAction.setToolBarData(new ToolBarData(icon));
		addLocalAction(clearAction);
	}

	private void clear() {
		textArea.setText("");
		eventList.clear();
	}

	void displayEvent(string eventStr) {

		eventList.add(eventStr);
		if (eventList.size() < LIMIT) {
			int caretPos = textArea.getCaretPosition();
			textArea.append(eventStr);
			textArea.setCaretPosition(caretPos + eventStr.length());
		}
		else {
			if (eventList.size() > LIMIT) {
				List<string> list = eventList.subList(100, eventList.size() - 1);
				eventList = new(list);
			}
			textArea.setText("");
			int length = 0;
			foreach (string str in eventList) {
				textArea.append(str);
				length += str.length();
			}
			textArea.setCaretPosition(length);
		}
	}

}
